export function append_node(tree: thread_structure['tree'], message: id) {
  let node: node = 0
  while (true) {
    const { children, focus } = tree[node]

    if (focus) {
      node = focus
    } else {
      break
    }
  }

  tree[node].children.push(message)
  tree[node].focus = message

  tree[message] = {
    children: [],
  }

  return tree
}

